package com.anitec.backend;
import com.anitec.backend.identity.application.*;
import com.anitec.backend.identity.domain.*;
import com.anitec.backend.identity.infrastructure.*;
import com.anitec.backend.identity.interfaceapi.*;
import com.anitec.backend.shared.domain.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.testcontainers.service.connection.ServiceConnection;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.ActiveProfiles;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.*;
import com.fasterxml.jackson.databind.*;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

@Testcontainers @ActiveProfiles("test")
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"email.delivery.mode=disabled","identity.password-recovery.enabled=false"})
class LegacyVerificationTests {
 @Container @ServiceConnection static PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:16-alpine");
 @Autowired IdentityService identity;@Autowired AccountRepository accounts;@Autowired JdbcTemplate jdbc;@Autowired EmailVerificationAuthenticator auth;@Autowired TestRestTemplate http;
 String pending(){String e=UUID.randomUUID()+"@example.invalid";identity.register(new IdentityService.RegisterCommand("Test","Legacy",e,"Initial-Password1!",Role.GANADERO));return e;}
 Account account(String e){return accounts.findByEmail(e).orElseThrow();}
 void install(String e,String code,java.util.function.BiFunction<UUID,UUID,byte[]> proof){UUID a=account(e).getId(),id=UUID.randomUUID();jdbc.update("UPDATE identity_accounts SET verification_emission_id=?,verification_verifier=?,verification_attempts=0,verification_sent_at=now(),verification_expires_at=now()+interval '10 minutes' WHERE id=?",id,proof.apply(a,id),a);}
 @Test void persistedAccountContainsOnlyProofEvenWithDeliveryDisabled(){String e=pending();var a=account(e);assertThat(a.getVerificationCode()).isNull();assertThat(a.getVerificationVerifier()).hasSize(32);assertThat(a.getVerificationVerifier()).isEqualTo(auth.sign(a.getId(),a.getVerificationEmissionId(),TestVerificationCodes.code(a)));assertThat(jdbc.queryForObject("SELECT verification_code FROM identity_accounts WHERE id=?",String.class,a.getId())).isNull();assertThat(jdbc.queryForObject("SELECT count(*) FROM identity_email_outbox WHERE account_id=?",Integer.class,a.getId())).isZero();identity.verifyEmail(e,TestVerificationCodes.code(a));assertThat(account(e).isVerified()).isTrue();}
 @Test void leadingZerosWorkThroughExistingRestContract(){String e=pending();install(e,"000007",(a,id)->auth.sign(a,id,"000007"));var r=http.postForEntity("/api/v1/auth/verify",Map.of("email",e,"code","000007"),JsonNode.class);assertThat(r.getStatusCode().value()).isEqualTo(200);assertThat(account(e).getVerificationVerifier()).isNull();assertThat(account(e).canSignIn()).isTrue();assertThat(r.getBody().toString()).doesNotContain("000007","verificationVerifier",TestVerificationCodes.KEY);}
 @Test void incorrectHmacNeverFallsBackToLegacyColumn(){String e=pending();install(e,"000007",(a,id)->{byte[] b=auth.sign(a,id,"000007");b[0]^=1;return b;});assertThatThrownBy(()->identity.verifyEmail(e,"000007")).isInstanceOf(DomainException.class);assertThat(account(e).getVerificationAttempts()).isEqualTo(1);assertThat(account(e).canSignIn()).isFalse();}
 @Test void verifierCopiedBetweenAccountsIsRejected(){String a=pending(),b=pending();byte[] proof=account(a).getVerificationVerifier();String code=TestVerificationCodes.code(account(a));install(b,code,(id,emission)->proof);assertThatThrownBy(()->identity.verifyEmail(b,code)).isInstanceOf(DomainException.class);assertThat(account(b).getVerificationAttempts()).isEqualTo(1);assertThat(account(b).isVerified()).isFalse();}
 @Test void verifierCopiedBetweenEmissionsIsRejected(){String e=pending();byte[] proof=account(e).getVerificationVerifier();String code=TestVerificationCodes.code(account(e));install(e,code,(id,emission)->proof);assertThatThrownBy(()->identity.verifyEmail(e,code)).isInstanceOf(DomainException.class);assertThat(account(e).isVerified()).isFalse();}
 @Test void wrongKeyProofIsRejected(){String e=pending();var wrong=new EmailVerificationHmac(new org.springframework.mock.env.MockEnvironment().withProperty("EMAIL_VERIFICATION_HMAC_KEY",EmailCryptoSettingsTests.key()));install(e,"000007",(a,id)->wrong.sign(a,id,"000007"));assertThatThrownBy(()->identity.verifyEmail(e,"000007")).isInstanceOf(DomainException.class);assertThat(account(e).getVerificationAttempts()).isEqualTo(1);}
 @Test void wrongPurposeProofIsRejected(){String e=pending();install(e,"000007",(a,id)->{try{var mac=javax.crypto.Mac.getInstance("HmacSHA256");mac.init(new javax.crypto.spec.SecretKeySpec(Base64.getDecoder().decode(TestVerificationCodes.KEY),"HmacSHA256"));return mac.doFinal(("password-recovery:v1\0"+a+"\0"+id+"\0"+"000007").getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception error){throw new IllegalStateException();}});assertThatThrownBy(()->identity.verifyEmail(e,"000007")).isInstanceOf(DomainException.class);assertThat(account(e).isVerified()).isFalse();}
 @Test void legacyInvalidationDoesNotRefundQuotaAndNewWindowRecovers(){String e=pending();String code=TestVerificationCodes.code(account(e));jdbc.update("UPDATE identity_accounts SET verification_verifier=NULL,verification_resends=5,verification_attempts=4,verification_window_started_at=now()-interval '1 hour',verification_sent_at=now()-interval '30 seconds' WHERE id=?",account(e).getId());var before=account(e);assertThatThrownBy(()->identity.verifyEmail(e,code)).isInstanceOf(DomainException.class);assertThatThrownBy(()->identity.resendVerificationCode(e)).isInstanceOf(VerificationThrottle.class);var unchanged=account(e);assertThat(unchanged.getVerificationResends()).isEqualTo(5);assertThat(unchanged.getVerificationAttempts()).isEqualTo(4);assertThat(unchanged.getVerificationWindowStartedAt()).isEqualTo(before.getVerificationWindowStartedAt());assertThat(unchanged.getVerificationSentAt()).isEqualTo(before.getVerificationSentAt());jdbc.update("UPDATE identity_accounts SET verification_window_started_at=now()-interval '25 hours',verification_sent_at=now()-interval '2 minutes' WHERE id=?",unchanged.getId());identity.resendVerificationCode(e);var fresh=account(e);assertThat(fresh.getVerificationResends()).isEqualTo(1);assertThat(fresh.getVerificationAttempts()).isZero();assertThat(fresh.getVerificationEmissionId()).isNotEqualTo(before.getVerificationEmissionId());identity.verifyEmail(e,TestVerificationCodes.code(fresh));assertThat(account(e).canSignIn()).isTrue();}
 @Test void invalidatedLegacyProofStillHonorsCooldown(){String e=pending();jdbc.update("UPDATE identity_accounts SET verification_verifier=NULL,verification_sent_at=now()-interval '30 seconds' WHERE id=?",account(e).getId());assertThatThrownBy(()->identity.resendVerificationCode(e)).isInstanceOfSatisfying(VerificationThrottle.class,t->assertThat(t.errorCode()).isEqualTo("RESEND_COOLDOWN"));assertThat(account(e).getVerificationResends()).isZero();}
 @Test void twoConcurrentConfirmationsConsumeExactlyOnce()throws Exception{String e=pending(),code=TestVerificationCodes.code(account(e));var gate=new CyclicBarrier(2);try(var pool=Executors.newFixedThreadPool(2)){Callable<Boolean> call=()->{gate.await(10,TimeUnit.SECONDS);try{identity.verifyEmail(e,code);return true;}catch(DomainException failure){return false;}};var a=pool.submit(call);var b=pool.submit(call);assertThat(List.of(a.get(20,TimeUnit.SECONDS),b.get(20,TimeUnit.SECONDS))).containsExactlyInAnyOrder(true,false);}assertThat(account(e).getVerificationVerifier()).isNull();}
 @Test void codesAndKeysAreAbsentFromNormalPublicErrorsAndLogs(){String e=pending(),code=TestVerificationCodes.code(account(e));var root=(ch.qos.logback.classic.Logger)org.slf4j.LoggerFactory.getLogger(org.slf4j.Logger.ROOT_LOGGER_NAME);var capture=new ch.qos.logback.core.read.ListAppender<ch.qos.logback.classic.spi.ILoggingEvent>();capture.start();root.addAppender(capture);try{String wrong=code.equals("000000")?"000001":"000000";var r=http.postForEntity("/api/v1/auth/verify",Map.of("email",e,"code",wrong),JsonNode.class);assertThat(r.getStatusCode().value()).isEqualTo(422);assertThat(r.getBody().toString()).doesNotContain(code,wrong,TestVerificationCodes.KEY,"verificationVerifier");for(var event:capture.list)assertThat(event.getFormattedMessage()).doesNotContain(code,wrong,TestVerificationCodes.KEY);}finally{root.detachAppender(capture);capture.stop();}}
 @Test void codeRequestDiagnosticStringsAreRedactedWithoutChangingJson()throws Exception{var request=new AuthController.VerifyRequest("private@example.invalid","000007","private-password");assertThat(request.toString()).doesNotContain("000007","private-password","private@example.invalid");assertThat(new ObjectMapper().readTree(new ObjectMapper().writeValueAsString(request)).path("code").asText()).isEqualTo("000007");var recovery=new PasswordRecoveryController.Confirm("private@example.invalid","000007","private-password");assertThat(recovery.toString()).doesNotContain("000007","private-password","private@example.invalid");}
}
